ALTER TABLE "notes" DROP CONSTRAINT "notes_encryption_mode_check", ADD CONSTRAINT "notes_encryption_mode_check" CHECK ((NOT "is_encrypted" AND "vault_id" IS NULL AND "encrypted_payload" IS NULL) OR ("is_encrypted" AND "vault_id" IS NOT NULL AND "encrypted_payload" IS NOT NULL AND "title" IS NULL AND "content" IS NULL AND jsonb_typeof("encrypted_payload") = 'object' AND coalesce("encrypted_payload"->>'version' = '1' AND "encrypted_payload"->>'algorithm' = 'AES-256-GCM' AND "encrypted_payload"->>'noteId' = "id"::text AND "encrypted_payload"->>'vaultId' = "vault_id"::text AND jsonb_typeof("encrypted_payload"->'title') = 'object' AND jsonb_typeof("encrypted_payload"->'body') = 'object', false)));